            //
            aOrbiterI = (aWandererD + RotL64(aIngress, 57U)) + 0x0E0585D0D948FCB5ULL;
            aOrbiterJ = ((aWandererA + RotL64(aScatter, 23U)) + RotL64(aCarry, 3U)) + 0x4A85331ED6984FC8ULL;
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 4U)) + 0xC80B5446745F5072ULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 27U)) & S_SALT1];
