            aOrbiterH = (aWandererK + RotL64(aScatter, 35U)) + 0xBC07613199382CDDULL;
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 41U)) + RotL64(aCarry, 53U)) + 0x99CAF9AEB632CD8DULL;
            aOrbiterA = (((aWandererE + RotL64(aCross, 29U)) + RotL64(aCarry, 23U)) + 0xCDDDBF5287D02397ULL) + aTwistOrbiterAssignSaltB[((aIndex + 125U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xB9F9D21475ACA821ULL;
