            //
            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0xEEECDEF5183DD44EULL) + aTwistOrbiterUpdateSaltE[((aIndex + 98U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xD82F1713B6899F43ULL;
