            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x155F4943E2AC6991ULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 104U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x6F9C3B7893644720ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x6B77B813C34F0D8BULL), 21U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0xB30A299ECB0C540EULL) + aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 180U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x62BD0FCE136E692DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x37721A8AEBA1EA9BULL), 53U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x7CD83A4E06ED690CULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x3935C9773DC97911ULL;
