            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererD = aWandererD ^ ((RotL64(aScatter, 47U) + aOrbiterC) + RotL64(aOrbiterE, 37U));
            aWandererA = aWandererA + (((RotL64(aIngress, 3U) + aOrbiterJ) + RotL64(aOrbiterC, 43U)) + aTwistWandererUpdateSaltA[(((255U - aIndex) + 32U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 37U) + aOrbiterI) + RotL64(aOrbiterE, 5U));
            aWandererK = aWandererK + (((RotL64(aPrevious, 13U) + aOrbiterA) + RotL64(aOrbiterH, 13U)) + RotL64(aCarry, 27U));
