            aWandererK = aWandererK ^ ((RotL64(aCross, 51U) + RotL64(aOrbiterD, 19U)) + aOrbiterG);
            aWandererG = aWandererG + (((RotL64(aPrevious, 4U) + RotL64(aOrbiterB, 3U)) + aOrbiterA) + RotL64(aCarry, 5U));
